import React from "react";
import Slider from "react-slick";
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";

const EventsSlider = () => {
  const settings = {
    dots: true,
    infinite: true,
    speed: 500,
    slidesToShow: 1,
    slidesToScroll: 1,
    arrows: true,
    autoplay: true,
    autoplaySpeed: 3000,
    pauseOnHover: true,
  };

  const slides = [
    { id: 1, title: "Slide 1" },
    { id: 2, title: "Slide 2" },
    { id: 3, title: "Slide 3" },
  ];

  return (<div>
    <div
      style={{
        position: "relative",
        maxWidth: "1112px",
        maxHeight:"413px",
        width: "100%",
        margin: "30px auto",
        border: "15px solid #00C26D",
        borderRadius: "10px",
        backgroundColor: "#293349",
        overflow: "hidden",
      }}
    >
     

      {/* Slider */}
      <Slider {...settings}>
        {slides.map((slide) => (
          <div
            key={slide.id}
            style={{
              height: "394px",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              color: "#fff",
              fontSize: "24px",
              fontWeight: "bold",
              backgroundColor: "#444",
            }}
          >
            {slide.title}
          </div>
        ))}
      </Slider>
    </div>
    </div>
  );
};

export default EventsSlider;
